def exact(actual, expected, label):
    if json.dumps(actual, sort_keys=True, default=lambda b: ["bytes", b.hex()]) != json.dumps(expected, sort_keys=True, default=lambda b: ["bytes", b.hex()]):
        raise ValueError(label)

def sha(content):
    return hashlib.sha256(content).hexdigest()

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or rel.startswith('/') or any(x in ('', '.', '..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p = root / safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute() != p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('unsafe file ' + rel)
    return p.read_bytes()

def validate_confirmation(c, receipt):
    exact(sha((json.dumps(c, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()), CONFIRMATION_SHA256, 'external325 confirmation')
    exact(sorted(receipt), ['encoding','original_display_sha256','original_display_size_bytes','text'], 'receipt fields')
    exact(receipt['encoding'], 'utf8-json-text', 'receipt encoding')
    raw = receipt['text'].encode()
    exact(sha(raw), RECEIPT_SHA256, 'original325 digest'); exact(len(raw), 86575, 'original325 length')
    exact(receipt['original_display_sha256'], RECEIPT_SHA256, 'receipt metadata digest')
    exact(receipt['original_display_size_bytes'], 86575, 'receipt metadata size')
    lines = receipt['text'].splitlines()
    exact(sum(x.startswith('PASS: ') for x in lines), 1004, 'complete1004 return')
    exact(lines.count('Result: PASS (1004 passes, 0 failures)'), 1, 'full1004 summary')
    log = '0c5caa7 (HEAD -> main, origin/main, origin/HEAD) Phase 1 step 325: review whole effect graph selector contracts and publication closure'
    exact(lines.count(log), 2, 'matching325 HEAD origin')
    if '[main 0c5caa7]' not in receipt['text'] or '92168f5..0c5caa7  main -> main' not in receipt['text']:
        raise ValueError('missing325 commit/push')
    return True

def verify_history(root, policy):
    binding = policy['baseline_sha256_bindings']
    serialized = (json.dumps(binding, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()
    exact(sha(serialized),BASELINE_JSON_SHA256,'exact accepted1512 manifest')
    exact(len(binding),1512,'accepted1512 file count')
    history = {}
    for rel,digest in binding.items():
        content = safe_file(root,rel)
        if rel == 'CHANGELOG.md':
            prefix = CHANGELOG_PREFIX.encode()
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            exact(content[:len(prefix)],prefix,'new CHANGELOG prefix')
            content = content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel] = content
    return history

def validate_design(design, prior, frozen, history):
    exact(design, DESIGN_SPEC, 'exact finite fault and independent conformance plan')
    exact(sha((json.dumps(prior, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()), PRIOR_DESIGN_SHA256, 'exact325 whole graph contract')
    for step, binding in design['previous_design_bindings'].items():
        exact(sha(history[binding['path']]), binding['sha256'], 'exact prior design '+step)
    exact(design['seven_requirements_bindings'], frozen['seven_review_bindings'], 'seven frozen requirements')
    exact(design['preserved_cross_obligations'], frozen['proof_obligations'], 'ten frozen cross obligations')
    exact(design['whole_graph_binding']['sha256'], PRIOR_DESIGN_SHA256, 'unclosed actual graph retained')
    exact(prior['proof_state']['actual_transitive_graph_complete'], False, 'static census never actual graph')
    exact(len(design['conformance_plan']), len(PLATFORMS)*len(CONFORMANCE_CASES), 'both platform plans complete')
    return True

def validate_tables(roadmap, obligations):
    exact(sha(roadmap),TABLE_HASHES[0],'exact typed roadmap')
    exact(sha(obligations),TABLE_HASHES[1],'exact obligation coverage table')
    return True

def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode('ascii')

def unique_pairs(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON field')
        result[key]=value
    return result


def simulate_private_lifecycle(value):
    exact(sorted(value), ['conditions','events','origin','recovery_budget','scope'], 'lifecycle fields')
    exact(value['origin'], 'synthetic-private-fixture', 'lifecycle origin')
    exact(value['scope'], 'finite-failure-contract-only-not-real-lifecycle', 'lifecycle scope')
    exact(sorted(value['conditions']), sorted(GATE_KEYS), 'lifecycle gate names')
    if any(type(x) is not bool for x in value['conditions'].values()): raise ValueError('typed lifecycle gates')
    if type(value['recovery_budget']) is not int or not 0 <= value['recovery_budget'] <= 8: raise ValueError('bounded recovery budget')
    if type(value['events']) is not list or len(value['events']) > 96: raise ValueError('bounded lifecycle events')
    gates = all(value['conditions'].values())
    fcursor = rcursor = pcursor = 0
    latched = not gates; hard = not gates; unsafe_target = False; pub_latched = False
    forward_live = recovery_live = publication_live = True
    authenticated = False; consumed = False; launch_spent = False; launched = False
    traps = guard = captured = backups = owned = binding = pin = False
    target_changed = False; target_attempted = False; children = False
    restored = verified = evidence = released = False
    record_durable = receipt_durable = False
    budget = value['recovery_budget']; spent = 0; attempts = set(); original_failure = None
    failure_recorded = False; artifacts = False; owned_unknown = False
    trace = []; denials = 0; launch_count = 0; claim_count = 0
    for event in value['events']:
        exact(sorted(event), ['action','outcome','raw_status'], 'typed event fields')
        action, outcome, status = event['action'], event['outcome'], event['raw_status']
        if type(action) is not str or action not in FORWARD+RECOVERY+PUBLICATION+HAZARDS+FORBIDDEN: raise ValueError('unknown lifecycle event')
        if type(outcome) is not str or outcome not in OUTCOMES: raise ValueError('typed event outcome')
        if status is not None and (type(status) is not int or status not in RAW_STATUSES): raise ValueError('typed raw event status')
        allowed = target_write = owned_write = False; attempted = False
        if action in HAZARDS:
            latched = True
            if not failure_recorded: original_failure = dict(action=action, outcome=outcome, raw_status=status); failure_recorded = True
            if pcursor: pub_latched = True
            if action in ['forward-expiry','forward-revocation']: forward_live = False
            elif action in ['recovery-expiry','recovery-revocation','budget-unknown']: recovery_live = False
            elif action == 'known-owned-signal': pass
            elif action == 'publication-revocation': publication_live = False; pub_latched = True
            else:
                hard = True
                if action in ['guard-lost','guard-replaced','worker-crash','service-crash']: guard = None
                if action in ['child-outcome-unknown','escaped-child','worker-crash']: children = None
                if action in ['all-rights-revocation','revocation-unknown','clock-unknown','boot-drift','epoch-drift']:
                    forward_live = recovery_live = publication_live = False
                if action in ['foreign-writer','phase-state-drift','raw-pin-drift','source-code-drift']: unsafe_target = True
            allowed = True
        elif action in FORBIDDEN:
            latched = True; denials += 1
            if pcursor: pub_latched = True
            if not failure_recorded: original_failure = dict(action=action, outcome=outcome, raw_status=status); failure_recorded = True
        else:
            if action in FORWARD:
                allowed = gates and not hard and not latched and forward_live and released is False and fcursor < len(FORWARD) and action == FORWARD[fcursor]
            elif action in RECOVERY:
                # Entry into finalization permanently stops forward execution, including a successful forward prefix.
                latched = True
                safe = gates and not hard and recovery_live and guard is True and traps and captured and consumed is True and launched is True and children is not None and released is False and budget > 0
                allowed = safe and rcursor < len(RECOVERY) and action == RECOVERY[rcursor]
                if action == 'restore-original-if-changed': allowed = allowed and children is True and not unsafe_target and (not target_changed or backups)
                if action == 'verify-original': allowed = allowed and children is True and restored and not unsafe_target
                if action == 'close-target-evidence': allowed = allowed and verified and children is True
                if action == 'release-target-control': allowed = allowed and verified and evidence and children is True
            else:
                allowed = gates and not hard and publication_live and not pub_latched and released is True and verified and evidence and children is True and pcursor < len(PUBLICATION) and action == PUBLICATION[pcursor]
            allowed = allowed and action not in attempts
            if allowed:
                attempted = True; attempts.add(action)
                if action in RECOVERY: budget -= 1; spent += 1
                target_write = action in TARGET_WRITES or action == 'restore-original-if-changed' and target_changed
                owned_write = action in OWNED_WRITES
                if target_write: target_attempted = True
                if owned_write: artifacts = True
                status_ok = status == 0 or action == 'nested-install-new-empty' and status == 20
                success = outcome == 'ok' and status_ok
                if success:
                    if action in FORWARD: fcursor += 1
                    elif action in RECOVERY: rcursor += 1
                    else: pcursor += 1
                    if action == 'authenticate-original-context': authenticated = True
                    elif action == 'consume-original-grant': consumed = True; claim_count += 1
                    elif action == 'spend-launch-slot': launch_spent = True
                    elif action == 'launch-one-worker': launched = True; launch_count += 1
                    elif action == 'stage1-arm-traps': traps = True
                    elif action == 'outer-guard-and-fresh-original': guard = True; captured = True
                    elif action == 'stage2-owned-work': owned = True
                    elif action == 'stage3-verify-original-backups': backups = True
                    elif action in TARGET_WRITES: target_changed = True
                    elif action == 'stage7-owned-binding': binding = True
                    if action == 'stage6-refresh-bind-raw-pin': pin = True
                    if action == 'drain-owned-children': children = True
                    elif action == 'restore-original-if-changed': target_changed = False; restored = True
                    elif action == 'verify-original': verified = not target_changed
                    elif action == 'close-target-evidence': evidence = True
                    elif action == 'release-target-control': released = True; guard = False
                    elif action == 'record-durability-confirmed': record_durable = True
                    elif action == 'last-receipt-durability-confirmed': receipt_durable = True
                else:
                    latched = True
                    if not failure_recorded: original_failure = dict(action=action, outcome=outcome, raw_status=status); failure_recorded = True
                    if action in PUBLICATION: pub_latched = True
                    if action in RECOVERY: hard = True
                    if outcome == 'unknown':
                        if action == 'consume-original-grant': consumed = None; hard = True
                        elif action == 'spend-launch-slot': launch_spent = None; hard = True
                        elif action == 'launch-one-worker': launched = None; children = None; hard = True
                        elif action in ['service-own-failure-barrier','authenticate-original-context','stage0-offline-bootstrap','stage0-close-unreviewed-capabilities','stage1-arm-traps','outer-guard-and-fresh-original']:
                            hard = True
                            if action == 'outer-guard-and-fresh-original': guard = None
                        elif action in OWNED_WRITES: owned_unknown = True
                        if target_write: unsafe_target = True
                        if action == 'drain-owned-children': children = None
                        if action == 'release-target-control': released = None; guard = None
                        if action in ['write-record-no-replace','record-durability-confirmed']: record_durable = None
                        if action in ['write-last-receipt-no-replace','last-receipt-durability-confirmed']: receipt_durable = None
            else:
                denials += 1; latched = True
                if action in PUBLICATION: pub_latched = True
                if not failure_recorded: original_failure = dict(action=action, outcome='denied', raw_status=status); failure_recorded = True
        trace.append(dict(action=action, outcome=outcome, raw_status=status, allowed=allowed, attempted=attempted,
            target_effect_attempted=attempted and target_write, owned_effect_attempted=attempted and owned_write,
            forward_latched=latched, hard_quarantine=hard, unsafe_target=unsafe_target, target_released=released,
            recovery_budget_remaining=budget, children_quiescent=children, guard=guard, original_failure=original_failure))
    closed = released is True and verified and evidence and children is True and pcursor == len(PUBLICATION) and not pub_latched and not hard
    return dict(trace=trace, model_scope_closed=closed, model_obligations_pending=not closed,
        model_consumed=consumed, model_launch_slot_spent=launch_spent, model_worker_launched=launched,
        model_claim_count=claim_count, model_launch_count=launch_count, model_forward_progress=fcursor,
        model_target_effect_attempted=target_attempted, model_target_state_known=not unsafe_target,
        model_target_restored_verified=restored and verified, model_children_quiescent=children,
        model_target_released=released, model_recovery_budget_spent=spent,
        model_artifacts_may_exist=artifacts, model_owned_outcome_unknown=owned_unknown,
        model_record_durability=record_durable, model_receipt_durability=receipt_durable,
        model_original_failure=original_failure, model_denials=denials,
        actual_runtime_lifecycle_proven=False, actual_conformance=False, actual_host_obligations_closed=False,
        actual_strong_safe_pause_confirmed=False, actual_runtime_authority=False,
        replay_authorized=False, new_grant_authorized=False, republish_authorized=False)

def enumerate_private_fault_cases():
    make = lambda action, outcome='ok', status=0: dict(action=action, outcome=outcome, raw_status=status)
    golden = [make(x) for x in FORWARD+RECOVERY+PUBLICATION]
    base = dict(origin='synthetic-private-fixture', scope='finite-failure-contract-only-not-real-lifecycle', conditions=dict.fromkeys(GATE_KEYS, True), recovery_budget=8)
    cases = [('golden', dict(base, events=golden))]
    for index, action in enumerate(FORWARD+RECOVERY+PUBLICATION):
        for outcome in ['known-failure','unknown']:
            changed = list(golden); changed[index] = make(action, outcome, 0 if outcome == 'known-failure' else None)
            cases.append(('boundary/'+str(index)+'/'+outcome, dict(base, events=changed)))
    for boundary in range(len(golden)+1):
        for action in HAZARDS+FORBIDDEN:
            cases.append(('interruption/'+str(boundary)+'/'+action, dict(base, events=golden[:boundary]+[make(action)]+golden[boundary:])))
    for key in GATE_KEYS:
        cases.append(('missing-gate/'+key, dict(base, conditions=dict(base['conditions'], **{key:False}), events=golden)))
    for budget in range(9): cases.append(('budget/'+str(budget), dict(base, recovery_budget=budget, events=golden)))
    for first in range(len(golden)):
        for second in range(first+1, len(golden)):
            for outcome1 in ['known-failure','unknown']:
                for outcome2 in ['known-failure','unknown']:
                    changed = list(golden); changed[first] = make(golden[first]['action'], outcome1, None if outcome1 == 'unknown' else 1); changed[second] = make(golden[second]['action'], outcome2, None if outcome2 == 'unknown' else 2)
                    cases.append(('pair/'+str(first)+'/'+str(second)+'/'+outcome1+'/'+outcome2, dict(base, events=changed)))
    return cases

def evaluate_private_conformance_index(value):
    exact(sorted(value), ['case_ids','conditions','origin','platform','scope'], 'conformance index fields')
    exact(value['origin'], 'synthetic-private-fixture', 'conformance origin')
    exact(value['scope'], 'future-independent-evidence-index-only', 'conformance scope')
    if type(value['platform']) is not str or value['platform'] not in PLATFORMS: raise ValueError('unknown conformance platform')
    exact(sorted(value['conditions']), sorted(CONFORMANCE_GATES), 'conformance evidence gates')
    if any(type(x) is not bool for x in value['conditions'].values()): raise ValueError('typed conformance evidence gates')
    if type(value['case_ids']) is not list or len(value['case_ids']) > len(CONFORMANCE_CASES) or any(type(x) is not str for x in value['case_ids']): raise ValueError('bounded typed evidence case IDs')
    if len(set(value['case_ids'])) != len(value['case_ids']) or any(x not in CONFORMANCE_CASES for x in value['case_ids']): raise ValueError('duplicate or foreign evidence ID')
    return dict(model_evidence_index_complete=set(value['case_ids'])==set(CONFORMANCE_CASES) and all(value['conditions'].values()),
        actual_independent_evidence_accepted=False, actual_platform_conformance=False,
        actual_implementation_complete=False, actual_runtime_authority=False, actual_strong_safe_pause_confirmed=False,
        opposite_platform_inferred=False, synthetic_or_self_oracle_is_conformance=False)









def run_historical(history):
    with tempfile.TemporaryDirectory(prefix='step326-exact325-') as directory:
        snapshot = Path(directory)/'slack-update'
        for rel,content in history.items():
            p = snapshot/safe_relative(rel); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(content)
        result = subprocess.run(['bash',str(snapshot/'tests/reference'/('test-'+PRIOR+'-harness.sh'))],capture_output=True)
        lines = result.stdout.decode().splitlines()
        if result.returncode or lines.count('Result: PASS (1004 passes, 0 failures)')!=1 or sum(x.startswith('PASS: ') for x in lines)!=1004:
            sys.stderr.buffer.write(result.stdout+result.stderr)
            raise ValueError('full exact1004 predecessor acceptance failed')
        return result.stdout

def main(root, out):
    if not root.is_dir() or root.absolute()!=root.resolve(): raise ValueError('unsafe repository root')
    for rel, digest in OWN_HASHES.items(): exact(sha(safe_file(root,rel)),digest,'changed326 input '+rel)
    fixture=root/FIXTURE; load=lambda suffix: json.loads((fixture/(BASE+suffix)).read_bytes())
    policy,design=load('-policy.json'),load('-design.json'); history=verify_history(root,policy)
    frozen=json.loads(history[FIXTURE+'/'+REQUIREMENTS_BASE+'-freeze.json']); prior=json.loads(history[FIXTURE+'/'+PRIOR+'-design.json'])
    validate_design(design,prior,frozen,history); validate_confirmation(load('-checkpoint-confirmation.json'),load('-step325-user-acceptance.json'))
    validate_tables(*[(fixture/(BASE+s)).read_bytes() for s in ['-finite-failure-contract.tsv','-independent-conformance-plan.tsv']])
    payloads={BASE+s:(fixture/(BASE+s)).read_bytes() for s in SUFFIXES}; log_name=BASE+'-predecessor-test.log'
    if not out.is_dir() or out.absolute()!=out.resolve(): raise ValueError('output must exist without symlink ancestors')
    if any((out/name).exists() or (out/name).is_symlink() for name in list(payloads)+[log_name]): raise ValueError('occupied output; no overwrite')
    payloads[log_name]=run_historical(history); exact(verify_history(root,policy),history,'history changed during validation')
    for rel,digest in OWN_HASHES.items(): exact(sha(safe_file(root,rel)),digest,'326 input changed during validation')
    created=[]
    try:
        for name,content in payloads.items():
            with (out/name).open('xb') as stream: created.append(out/name); stream.write(content)
    except BaseException:
        for p in reversed(created): p.unlink()
        raise
    print('exact_step325_acceptance\tPASS (1004 passes, 0 failures)')
    print('step326_finite_failure_and_conformance_plan_status\tPASS')
    print('actual_runtime_lifecycle_or_conformance_proven\tno'); print('actual_dispatch_or_publication_authorized\tno')
    print('operational_readiness\tno'); print('strong_safe_pause\tno')
    print('last_confirmed_strong_safe_pause_step\t318'); print('next_stage_authorized\tno')

if __name__ == '__main__':
    try: main(Path(sys.argv[1]).absolute(),Path(sys.argv[2]).absolute())
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print('ERROR: '+str(exc),file=sys.stderr);sys.exit(1)
